<template><div class="page"><div class="head"><div><h2>设备分类</h2><p>定义不同设施设备的基础资料字段，并关联对应巡检表单。</p></div><el-button type="primary" @click="edit()">新增分类</el-button></div><el-table :data="rows"><el-table-column prop="code" label="分类编码"/><el-table-column prop="name" label="分类名称"/><el-table-column prop="systemName" label="所属系统"/><el-table-column label="扩展资料"><template #default="s">{{parse(s.row.baseFieldsJson).length}} 项</template></el-table-column><el-table-column label="关联表单"><template #default="s"><el-tag v-for="t in s.row.templates" :key="t.id" class="tag">{{kindText[t.inspectionKind]||t.inspectionKind}}：{{t.templateName}}</el-tag></template></el-table-column><el-table-column label="状态"><template #default="s"><el-tag :type="s.row.enabled?'success':'info'">{{s.row.enabled?'启用':'停用'}}</el-tag></template></el-table-column><el-table-column label="操作"><template #default="s"><el-button link type="primary" @click="edit(s.row)">编辑</el-button></template></el-table-column></el-table>
<el-dialog v-model="visible" title="设备分类" width="900"><el-form label-width="90"><el-row :gutter="12"><el-col :span="12"><el-form-item label="分类编码"><el-input v-model="form.code"/></el-form-item></el-col><el-col :span="12"><el-form-item label="分类名称"><el-input v-model="form.name"/></el-form-item></el-col><el-col :span="12"><el-form-item label="所属系统"><el-input v-model="form.systemName" placeholder="例如：消防系统"/></el-form-item></el-col><el-col :span="12"><el-form-item label="排序"><el-input-number v-model="form.sortOrder"/></el-form-item></el-col></el-row><el-form-item label="说明"><el-input v-model="form.description" type="textarea"/></el-form-item></el-form><div class="sub"><b>分类专属基础字段</b><el-button @click="addField">增加字段</el-button></div><div v-for="(f,i) in form.baseFields" :key="i" class="field"><el-input v-model="f.key" placeholder="字段编码"/><el-input v-model="f.label" placeholder="字段名称"/><el-select v-model="f.controlType"><el-option label="文本" value="TEXT"/><el-option label="数值" value="NUMBER"/><el-option label="日期" value="DATE"/><el-option label="是否" value="BOOLEAN"/></el-select><el-input v-model="f.unit" placeholder="单位"/><el-button link type="danger" @click="form.baseFields.splice(i,1)">删除</el-button></div><div class="sub"><b>关联巡检表单</b><el-button @click="addTemplate">增加关联</el-button></div><div v-for="(t,i) in form.templates" :key="i" class="template-row"><el-select v-model="t.inspectionKind"><el-option v-for="(v,k) in kindText" :key="k" :label="v" :value="k"/></el-select><el-select v-model="t.templateId" filterable><el-option v-for="x in templates" :key="x.id" :label="x.name" :value="x.id"/></el-select><el-button link type="danger" @click="form.templates.splice(i,1)">删除</el-button></div><el-form-item label="启用"><el-switch v-model="form.enabled"/></el-form-item><template #footer><el-button @click="visible=false">取消</el-button><el-button type="primary" @click="save">保存</el-button></template></el-dialog></div></template>
<script setup lang="ts">import{ref,onMounted}from'vue';import{ElMessage}from'element-plus';import{inspectionEquipmentApi}from'@/api/inspectionEquipment';import{inspectionApi}from'@/api/inspection';const rows=ref<any[]>([]),templates=ref<any[]>([]),visible=ref(false),form=ref<any>({});const kindText:any={ROUTINE:'日常',DAILY:'日检',WEEKLY:'周检',MONTHLY:'月检',QUARTERLY:'季度',YEARLY:'年度',SPECIAL:'专项'};const parse=(s:any)=>{try{return typeof s==='string'?JSON.parse(s):s||[]}catch{return[]}};async function load(){[rows.value,templates.value]=await Promise.all([inspectionEquipmentApi.categories(),inspectionApi.templates()]) as any}function edit(r:any={}){form.value={id:r.id,code:r.code||'',name:r.name||'',systemName:r.systemName||'',description:r.description||'',sortOrder:r.sortOrder||0,enabled:r.id?!!r.enabled:true,baseFields:parse(r.baseFieldsJson),templates:(r.templates||[]).map((x:any)=>({...x}))};visible.value=true}function addField(){form.value.baseFields.push({key:'',label:'',controlType:'TEXT',unit:''})}function addTemplate(){form.value.templates.push({inspectionKind:'ROUTINE',templateId:null})}async function save(){await inspectionEquipmentApi.saveCategory(form.value);ElMessage.success('设备分类已保存');visible.value=false;load()}onMounted(load)
</script>
<style scoped>.page{padding:20px}.head,.sub{display:flex;justify-content:space-between;align-items:center}.head h2{margin:0}.head p{color:#777}.tag{margin:2px}.sub{margin:16px 0 8px}.field{display:grid;grid-template-columns:1fr 1.4fr 1fr .7fr auto;gap:8px;margin-bottom:8px}.template-row{display:grid;grid-template-columns:180px 1fr auto;gap:8px;margin-bottom:8px}@media(max-width:768px){.page{padding:10px}.field,.template-row{grid-template-columns:1fr}.head{align-items:flex-start}}</style>
